// ============ NEV SETTINGS ============  edit these, nothing else. Setup: README.md
const settings = {
  ME: 'Mate',
  EX_NAME: 'your ex',
  EX_NUMBER: '+61400000000',               // the real number, used by the optional ex line
  EX_AUTO_SEND: false,                     // false = Nev writes the excuse and YOU decide. true = Twilio sends it
  TELEGRAM_CHAT_ID: 'YOUR_TELEGRAM_CHAT_ID',
  TELEGRAM_BOT_TOKEN: 'YOUR_TELEGRAM_BOT_TOKEN',   // the poll needs it
  TWILIO_FROM: '+61400000000',
  TIMEZONE: 'Australia/Perth',
  HOME: { lat: -31.9523, lng: 115.8613, address: 'Your address, Suburb WA 6000' },
  BIG_NIGHT_STEPS: 6000,                   // steps between midnight and 2am that mean "a big one"
  FOOD: { store: "McDonald's", items: ['Big Brekkie Burger'], url: 'https://www.ubereats.com/au/search?q=McDonalds', capAud: 25 },
  CHEMIST: { store: 'the closest convenience store or chemist', items: ['Blue Powerade', 'Hydralyte', 'Panadol'],
             url: 'https://www.ubereats.com/au/search?q=Powerade', capAud: 40 },
  SPORTSBET_LIMITS_URL: 'https://www.sportsbet.com.au/',   // paste the deposit limit page from your own account
  SAUNA_TIME: '15:00',
  SAUNA_CAP_AUD: 60,
  MY_CALENDAR: 'primary',
  BROWSER_PROFILE_ID: 'YOUR_BROWSER_USE_PROFILE_ID',       // the saved browser you logged in to once
  AGENT_MAX_USD: 1,                        // the most one browser agent run may cost
  FORCE_GO: false,                         // true = run the morning even if it wasn't a big one (for testing)
  MODEL: 'claude-sonnet-5-5',
};
const inp = $input.first().json;
const p = String(inp.webhookUrl || '');
const upEvent = (((inp.body || {}).data || {}).attributes || {}).eventType;
const lane = p.includes('nev-up') ? (upEvent === 'TRANSACTION_CREATED' ? 'up' : 'ignore') : p.includes('nev-ex') ? 'ex' : p.includes('nev-wake') ? 'wake' : 'tap';
const body = (inp.body && Object.keys(inp.body).length) ? inp.body : (inp.query || {});
return [{ json: { ...settings, lane, input: body } }];

const KIND_RULES = [
  ['sportsbet', /sportsbet|ladbrokes|tab\b|neds|bet365|betr\b|pointsbet|unibet/i],
  ['kebab', /kebab|hsp|souvlaki|gyro|pizza|maccas|mcdonald|hungry jack|kfc|red rooster|chicken treat|takeaway/i],
  ['uber', /uber|didi|ola\b|taxi|13cabs/i],
  ['bar', /\bbar\b|pub\b|tavern|hotel|brewery|brewing|nightclub|club\b|lounge|arms\b|inn\b|anchor/i],
];
const kindOf = (m, upCategory) => {
  if (upCategory === 'pubs-and-bars') return 'bar';
  for (const [k, re] of KIND_RULES) if (re.test(m || '')) return k;
  return 'unknown';
};

// One card tap, from the iPhone Wallet Shortcut or Up Bank, in one shape.
const S = $('Nev settings').first().json;
let merchant, amount, upCategory;
if (S.lane === 'up') {
  const d = $input.first().json.data;
  merchant = d.attributes.description;
  amount = Math.max(0, -(+d.attributes.amount.value));   // money in (refunds, pay) doesn't count
  upCategory = d.relationships && d.relationships.category && d.relationships.category.data && d.relationships.category.data.id;
} else {
  merchant = String(S.input.merchant || S.input.name || 'Unknown');
  amount = Math.abs(parseFloat(String(S.input.amount || '0').replace(/[^0-9.\-]/g, '')) || 0);
}
const at = S.input.at || new Intl.DateTimeFormat('en-GB', { timeZone: S.TIMEZONE, hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date());
return [{ json: { merchant, amount, at, kind: kindOf(merchant, upCategory),
  body: { model: S.MODEL, max_tokens: 1000, messages: [{ role: 'user', content:
    `A card transaction at "${merchant}". Reply with one word: bar, kebab, sportsbet, uber or other. "bar" means pubs, bars and clubs. "kebab" means any late-night food.` }] } } }];

const t = $('Read the tap').first().json;
const w = $input.first().json.content.map(c => c.text || '').join('').trim().toLowerCase();
return [{ json: { ...t, kind: ['bar', 'kebab', 'sportsbet', 'uber'].includes(w) ? w : 'other' } }];

// Tonight's tab lives in this workflow's own memory. A new night starts at midday.
const S = $('Nev settings').first().json;
const t = $input.first().json;
const st = $getWorkflowStaticData('global');
const date = new Intl.DateTimeFormat('en-CA', { timeZone: S.TIMEZONE }).format(new Date(Date.now() - 12 * 3600e3));
if (!st.night || st.night.date !== date) st.night = { date, tabs: [], exAttempts: 0, started: false, woke: false };
const n = st.night;
n.tabs.push({ at: t.at, merchant: t.merchant, amount: t.amount, kind: t.kind });
const afterMidnight = t.at < '06:00';
const startNow = t.kind === 'bar' && afterMidnight && !n.started;
if (startNow) n.started = true;
return [{ json: { ...t, startNow } }];

// One attempt on the ex. Counts only. Nev never records a call or reads a message.
const S = $('Nev settings').first().json;
const st = $getWorkflowStaticData('global');
const date = new Intl.DateTimeFormat('en-CA', { timeZone: S.TIMEZONE }).format(new Date(Date.now() - 12 * 3600e3));
if (!st.night || st.night.date !== date) st.night = { date, tabs: [], exAttempts: 0, started: false, woke: false };
st.night.exAttempts += 1;
const num = S.EX_NUMBER.replace(/[^+0-9]/g, '');
return [{ json: { twiml: `<?xml version="1.0" encoding="UTF-8"?><Response><Dial>${num}</Dial></Response>` } }];

// You're awake. Was it a big one? Bar taps after midnight AND the step count.
const S = $('Nev settings').first().json;
const st = $getWorkflowStaticData('global');
const n = st.night || { tabs: [], exAttempts: 0 };
const steps = parseInt(String(S.input.steps ?? S.input.steps_12_2 ?? '0').replace(/[^0-9]/g, ''), 10) || 0;
const tabs = n.tabs || [];
const sum = k => tabs.filter(t => t.kind === k).reduce((a, t) => a + t.amount, 0);
const bigOne = !!n.started && steps >= S.BIG_NIGHT_STEPS;
const go = S.lane === 'wake' && (bigOne || S.FORCE_GO) && !n.woke;
if (go && st.night) st.night.woke = true;
return [{ json: { go, tabs, steps, exAttempts: n.exAttempts || 0,
  beers: sum('bar'), kebabs: sum('kebab'), sportsbet: sum('sportsbet'), ubers: sum('uber'),
  total: tabs.reduce((a, t) => a + t.amount, 0) } }];

// The workaround: Uber Eats has no public ordering API, so a browser agent uses your own
// logged-in account the way you would. It stops rather than guesses.
const S = $('Nev settings').first().json;
const o = S.FOOD;
const task = `You are logged in to the user's own Uber Eats account. Deliver to ${S.HOME.address}, using the saved address and saved payment method.
Order from ${o.store}: ${o.items.join(', ')}. If an item is sold out, pick the nearest equivalent. Never add anything else.
Stop WITHOUT ordering and return ordered=false with the reason if: the total including fees is over A$${o.capAud}; you are logged out; a CAPTCHA, a code or a security check appears; or the store is closed.
Do not try to get around any of those. Otherwise place the order and return ordered=true, the total and the ETA.`;
const run = { task, startUrl: o.url, profileId: S.BROWSER_PROFILE_ID, maxCostUsd: S.AGENT_MAX_USD,
  outputSchema: { type: 'object', properties: { ordered: { type: 'boolean' }, total: { type: 'number' }, eta: { type: 'string' }, reason: { type: 'string' } }, required: ['ordered', 'reason'] } };
return [{ json: { run } }];

const S = $('Nev settings').first().json;
const o = S.FOOD;
const out = $input.first().json.output || {};
const ok = $input.first().json.status === 'completed' && out.ordered === true;
return [{ json: { ok, store: o.store, items: o.items, url: o.url, total: out.total, eta: out.eta || '', reason: out.reason || 'the agent stopped' } }];

// The workaround: Uber Eats has no public ordering API, so a browser agent uses your own
// logged-in account the way you would. It stops rather than guesses.
const S = $('Nev settings').first().json;
const o = S.CHEMIST;
const task = `You are logged in to the user's own Uber Eats account. Deliver to ${S.HOME.address}, using the saved address and saved payment method.
Order from ${o.store}: ${o.items.join(', ')}. If an item is sold out, pick the nearest equivalent. Never add anything else.
Stop WITHOUT ordering and return ordered=false with the reason if: the total including fees is over A$${o.capAud}; you are logged out; a CAPTCHA, a code or a security check appears; or the store is closed.
Do not try to get around any of those. Otherwise place the order and return ordered=true, the total and the ETA.`;
const run = { task, startUrl: o.url, profileId: S.BROWSER_PROFILE_ID, maxCostUsd: S.AGENT_MAX_USD,
  outputSchema: { type: 'object', properties: { ordered: { type: 'boolean' }, total: { type: 'number' }, eta: { type: 'string' }, reason: { type: 'string' } }, required: ['ordered', 'reason'] } };
return [{ json: { run } }];

const S = $('Nev settings').first().json;
const o = S.CHEMIST;
const out = $input.first().json.output || {};
const ok = $input.first().json.status === 'completed' && out.ordered === true;
return [{ json: { ok, store: o.store, items: o.items, url: o.url, total: out.total, eta: out.eta || '', reason: out.reason || 'the agent stopped' } }];

// Anything the agent couldn't finish becomes a link you tap yourself.
const a = $('Result (food)').first().json, b = $('Result (chemist)').first().json;
const line = (e, r) => r.ok ? `${e} ${r.items.join(', ')}${r.eta ? ` · ${r.eta}` : ''}`
  : `${e} ${r.items.join(', ')}\n⚠️ ${r.reason}\n<a href="${r.url}">Tap here to order it yourself</a>`;
const head = a.ok && b.ok ? "💊 <b>You're awake. Care package ordered.</b>" : "💊 <b>You're awake. Care package nearly sorted.</b>";
return [{ json: { msg: `${head}\n\n${line('🍔', a)}\n${line('🥤', b)}` } }];

// The damage report. Numbers only, on purpose: Aaron cut every quip.
const S = $('Nev settings').first().json;
const n = $('Was it a big one?').first().json;
const money = v => '$' + Number(v).toFixed(2).replace(/\.00$/, '');
const report = ['🚨 THE DAMAGE REPORT', '',
  `📱 Calls to ${S.EX_NAME}: ${n.exAttempts}`,
  `🍺 Beers: ${money(n.beers)}`,
  `🥙 Kebabs: ${money(n.kebabs)}`,
  `🎰 Sportsbet: ${money(n.sportsbet)}`,
  `💸 Total: ${money(n.beers + n.kebabs + n.sportsbet)}`].join('\n');   // adds up to the lines above
return [{ json: { report } }];

// Has the poll been tapped? Matched on THIS poll's id, because Telegram keeps old answers around.
const pollId = String($('Send the poll').first().json.result.poll.id);
let a = null;
for (const u of $input.first().json.result || []) {
  const p = u.poll_answer;
  if (p && String(p.poll_id) === pollId && (p.option_ids || []).length) a = p;   // last tap wins
}
const giveUp = !a && ($runIndex || 0) >= 480;   // no tap in time counts as "let me think"
return [{ json: { answered: !!a || giveUp, data: { approved: !!a && a.option_ids[0] === 0 } } }];

const S = $('Nev settings').first().json;
const n = $('Was it a big one?').first().json;
const prompt = `${S.ME} tried to contact their ex ${S.EX_NAME} ${n.exAttempts} times last night while drunk.
Write the text ${S.ME} sends this morning: a short, funny, face-saving apology that asks for nothing and doesn't reopen anything.
Under 25 words. No emojis. No em dashes. Output only the message.`;
return [{ json: { body: { model: S.MODEL, max_tokens: 1500, messages: [{ role: 'user', content: prompt }] } } }];

// Sportsbet has no public API, so this is a browser agent too. It can only ever go DOWN.
const S = $('Nev settings').first().json;
const task = `You are logged in to the user's own Sportsbet account. Open the deposit limit settings.
Set the daily deposit limit to the lowest amount the site accepts (zero if it allows zero).
Only ever lower a limit. Never raise a limit, deposit, withdraw or place a bet.
Stop and return done=false with the reason if you are logged out or a CAPTCHA, code or security check appears. Do not try to get around them.
Return done=true and the new limit once the site confirms it.`;
return [{ json: { run: { task, startUrl: S.SPORTSBET_LIMITS_URL, profileId: S.BROWSER_PROFILE_ID, maxCostUsd: S.AGENT_MAX_USD,
  outputSchema: { type: 'object', properties: { done: { type: 'boolean' }, limit: { type: 'string' }, reason: { type: 'string' } }, required: ['done', 'reason'] } } } }];

const S = $('Nev settings').first().json;
return [{ json: { body: { textQuery: 'sauna', maxResultCount: 5,
  locationBias: { circle: { center: { latitude: S.HOME.lat, longitude: S.HOME.lng }, radius: 25000 } } } } }];

// Most saunas have no booking API. The agent uses their own booking page, and stops at payment over the cap.
const S = $('Nev settings').first().json;
const p = ($input.first().json.places || [])[0];
if (!p) return [{ json: { skip: true, sauna: { name: 'a sauna near you', url: '' } } }];
const sauna = { name: p.displayName.text, url: p.websiteUri || p.googleMapsUri || '', address: p.formattedAddress || '' };
const task = `Book one session at ${sauna.name} for today, as close to ${S.SAUNA_TIME} as possible, on its own booking page.
Stop and return booked=false with the reason if: there is no online booking; the price is over A$${S.SAUNA_CAP_AUD}; a card number is needed that isn't saved; or a CAPTCHA or security check appears.
Return booked=true and the booked time once confirmed.`;
return [{ json: { skip: false, sauna, run: { task, startUrl: sauna.url, profileId: S.BROWSER_PROFILE_ID, maxCostUsd: S.AGENT_MAX_USD,
  outputSchema: { type: 'object', properties: { booked: { type: 'boolean' }, time: { type: 'string' }, reason: { type: 'string' } }, required: ['booked', 'reason'] } } } }];

const S = $('Nev settings').first().json;
const night = $('Was it a big one?').first().json;
const excuse = $('Claude: the excuse').first().json.content.map(c => c.text || '').join('').trim();
if (!excuse) throw new Error('Claude returned no text for the excuse');
const lim = $('Agent done? (sportsbet)').first().json;
const limOk = lim.status === 'completed' && (lim.output || {}).done === true;
const s = $('Brief: sauna').first().json;
const r = $input.first().json;
const booked = !s.skip && r.status === 'completed' && (r.output || {}).booked === true;
const time = booked ? ((r.output || {}).time || S.SAUNA_TIME) : S.SAUNA_TIME;
const lines = ['🩺 <b>Damage controlled.</b>', ''];
if (night.exAttempts > 0) lines.push(S.EX_AUTO_SEND ? `📱 Excuse sent to ${S.EX_NAME}: "${excuse}"` : `📱 Your excuse for ${S.EX_NAME}, if you want it:\n${excuse}`);
lines.push(limOk ? `🎰 Sportsbet deposit limit now ${(lim.output || {}).limit || 'at its lowest'}` : `🎰 Couldn't cap Sportsbet myself. <a href="${S.SPORTSBET_LIMITS_URL}">Tap here to do it</a>`);
lines.push(booked ? `🧖 ${s.sauna.name}, booked for ${time}` : `🧖 ${s.sauna.name}, couldn't book it. ${s.sauna.url ? `<a href="${s.sauna.url}">Tap here</a>, ` : ''}I've held ${S.SAUNA_TIME} in your calendar`);
lines.push('', 'Drink your Hydralyte.');
const date = new Intl.DateTimeFormat('en-CA', { timeZone: S.TIMEZONE }).format(new Date());
return [{ json: { msg: lines.join('\n'), excuse, start: `${date}T${/^\d\d:\d\d$/.test(time) ? time : S.SAUNA_TIME}:00`,
  sendExcuse: !!S.EX_AUTO_SEND && night.exAttempts > 0, sauna: s.sauna.name } }];
